29 |         return Object.keys(skillRegistry).map(key => {
30 |             const skill = skillRegistry[key];
31 |             const func = {
32 |                 name: key,
33 |                 description: skill.description
34 |             };
35 |             if (skill.parameters) {
36 |                 func.parameters = skill.parameters;
37 |             } else {
38 |                 // OpenAI yêu cầu parameters phải có, dù rỗng
39 |                 func.parameters = { type: "object", properties: {} };
40 |             }
