{"file_path":"C:/Users/Xon/Documents/bridge_server/prime_checker.py","content":"import math

def is_prime(n):
 """
 Hàm kiểm tra xem một số có phải là số nguyên tố hay không.
 """
 if n < 2:
 return False
 if n == 2:
 return True
 if n % 2 == 0:
 return False
 # Chỉ cần kiểm tra các số lẻ từ 3 đến căn bậc hai của n
 for i in range(3, int(math.sqrt(n)) + 1, 2):
 if n % i == 0:
 return False
 return True

if __name__ == "__main__":
