{"file_path":"C:/Users/Xon/Documents/bridge_server/prime_checker.py","content":"import math

def is_prime(n):
 """
 Kiểm tra xem một số có phải là số nguyên tố hay không.
 """
 if n <= 1:
 return False
 if n <= 3:
 return True
 if n % 2 == 0 or n % 3 == 0:
 return False

 # Chỉ cần kiểm tra các ước từ 5 đến căn bậc hai của n
 # với bước nhảy 6 (kiểm tra i và i+2)
 i = 5
 while i * i <= n:
 if n % i == 0 or n % (i + 2) == 0:
 return False
 i += 6
 return True

if __name__ == "__main__":
 print("Các số nguyên tố từ 1 đến 200:")
 primes = []
 for num in range(1, 201):
 if is_prime(num):
 primes.append(num)

 # In kết quả
 print(primes)
 print(f"\nTổng cộng có {len(primes)} số nguyên tố.")"}
